@pytest.mark.parametrize(
    "txid, kinds, parent_ids, fetched_parent_ids, taproot_requires_all_prevouts",
    CASES,
    ids=[case[0][:12] for case in CASES],
)
def test_confirmed_mainnet_signatures(
    txid: str,
    kinds: list[str],
    parent_ids: list[str],
    fetched_parent_ids: list[str],
    taproot_requires_all_prevouts: list[bool],
) -> None:
    spend = bdk.Transaction(bytes.fromhex(SPENDS[txid]))
    assert str(spend.compute_txid()) == txid
    assert len(spend.input()) == len(parent_ids) == len(taproot_requires_all_prevouts)
    assert len(set(fetched_parent_ids)) == len(fetched_parent_ids)
    assert set(fetched_parent_ids) <= set(parent_ids)

    # A parent can be shared across spends. Only parents fetched for this spend may
    # provide its prevouts; the rest are intentionally missing history.
    prevouts: list[Prevout | None] = []
    for txin, parent_id in zip(spend.input(), parent_ids, strict=True):
        assert str(txin.previous_output.txid) == parent_id
        if parent_id not in fetched_parent_ids:
            prevouts.append(None)
            continue
        parent = bdk.Transaction(bytes.fromhex(PARENTS[parent_id]))
        assert str(parent.compute_txid()) == parent_id
        output = parent.output()[txin.previous_output.vout]
        prevouts.append(
            Prevout(
                script_pubkey=bytes(output.script_pubkey.to_bytes()),
                value=output.value.to_sat(),
            )
        )

    verdicts = verify_transaction(spend, prevouts, [True] * len(prevouts)).verdicts
    # Only Taproot non-ANYONECANPAY key-path sighashes commit to every sibling prevout.
    # Legacy and SegWit inputs are verifiable from their own prevout alone.
    missing_any = any(prevout is None for prevout in prevouts)
    expected = [
        InputVerdict.unchecked if prevout is None or (missing_any and requires_all) else InputVerdict.valid
        for prevout, requires_all in zip(prevouts, taproot_requires_all_prevouts, strict=True)
    ]
    assert verdicts == expected, (kinds, verdicts, expected)
